// ─────────────────────────────────────────────────────────────
//  AKARI · GLOFOX MEMBER SYNC · CONFIG
//  Once a day: count active Glofox members per Capacity row and update Active Members.
// ─────────────────────────────────────────────────────────────
const cfg = {
  airtableBaseId: 'appXXXXXXXXXXXXXX', // same base as the waitlist workflow
  airtableApi: 'https://api.airtable.com/v0',
  tables: { capacity: 'Capacity', log: 'Activity Log', waitlist: 'Waitlist' },

  glofoxApi: 'https://YOUR-GLOFOX-PROXY/prod', // Glofox API base (your proxy), no trailing slash
  // Each branch's members are listed with that branch's ID. A member is counted once, however many branches list them.
  branches: [
    { id: '64c9870292e260894f0247a4', name: 'Williamsburg' },
    { id: '67cf4fe8ef346c3817003b8f', name: 'Greenpoint' },
    { id: '6a1741e58f61326070010c0a', name: 'LES' },
  ],

  // Everyone holding a membership counts, so a pause or a failed payment doesn't open a spot (Jack, 11 Nov).
  // Someone drops out of the count only once their membership is cancelled in Glofox.
  countStatuses: ['ACTIVE', 'PAUSED', 'LOCKED', 'FUTURE'],
  maxDropShare: 0.5, // a queue whose count falls by more than this share in one day is not written; it is flagged instead
  minRowsForDropCheck: 20, // ...only for queues with at least this many active members today
};

const base = `${cfg.airtableApi}/${cfg.airtableBaseId}`;
cfg.urls = {
  capacity: `${base}/${encodeURIComponent(cfg.tables.capacity)}`,
  log: `${base}/${encodeURIComponent(cfg.tables.log)}`,
  waitlist: `${base}/${encodeURIComponent(cfg.tables.waitlist)}`,
};

return [{ json: { cfg } }];

// One item per Glofox branch; the next node pages through that branch's member list.
const { cfg } = $('Config').first().json;
return cfg.branches.map((b) => ({ json: { branch: b.id, name: b.name } }));

// Counts members per Glofox membership name, for the statuses in countStatuses.
// Refuses to continue on an error page or an incomplete list, so a partial read never overwrites Active Members.
const { cfg } = $('Config').first().json;
const statuses = new Set(cfg.countStatuses.map((s) => String(s).toUpperCase()));
const pages = $input.all().map((i) => i.json);

const problems = [];
const seen = new Set();
const perBranch = {}; // branch id → { expected, got }
const counts = {}; // lower-case membership name → { name, n }
const holders = {}; // lower-case email → membership names held (same statuses), for the waitlist's existing-member flag
const held = {}; // lower-case email → [{ id, name, status, start, price, monthly }], for verifying waitlist purchases
const accounts = {}; // lower-case email → true for every Glofox account (members and pay-as-you-go)
for (const p of pages) {
  if (!p || p.success === false || p.message || !Array.isArray(p.data)) {
    problems.push(String((p && (p.message || p.error)) || 'unreadable page').slice(0, 200));
    continue;
  }
  for (const m of p.data) {
    const b = m.branch_id || '?';
    perBranch[b] = perBranch[b] || { expected: Number(p.total_count) || 0, got: 0 };
    perBranch[b].got += 1;
    if (seen.has(m._id)) continue;
    seen.add(m._id);
    const ms = m.membership || {};
    for (const raw of [m.email, m.account_email, m.contact_email]) {
      const email = String(raw || '').trim().toLowerCase();
      if (email) accounts[email] = true;
    }
    if (!ms.membership_name || !statuses.has(String(ms.status || '').toUpperCase())) continue;
    const key = ms.membership_name.trim().toLowerCase();
    counts[key] = counts[key] || { name: ms.membership_name.trim(), n: 0 };
    counts[key].n += 1;
    for (const raw of [m.email, m.account_email, m.contact_email]) {
      const email = String(raw || '').trim().toLowerCase();
      if (!email) continue;
      holders[email] = holders[email] || [];
      if (!holders[email].includes(ms.membership_name.trim())) holders[email].push(ms.membership_name.trim());
      held[email] = held[email] || [];
      const id = ms.user_membership_id || ms._id || m._id;
      if (!held[email].some((h) => h.id === id)) {
        const start = Number(ms.start_date) || 0;
        held[email].push({
          id,
          name: ms.membership_name.trim(),
          status: String(ms.status || '').toUpperCase(),
          start: start ? new Date(start > 1e11 ? start : start * 1000).toISOString() : null,
          price: Number(ms.plan_price) || 0,
          monthly: String(ms.duration_time_unit || '').toLowerCase() === 'month' && Number(ms.duration_time_unit_count || 1) === 1,
        });
      }
    }
  }
}
for (const b of cfg.branches) {
  const r = perBranch[b.id];
  if (!r) problems.push(`${b.name}: no members returned`);
  else if (Math.abs(r.got - r.expected) > Math.max(5, r.expected * 0.01)) problems.push(`${b.name}: read ${r.got} of ${r.expected} members`);
}
if (problems.length) throw new Error(`Glofox sync stopped, nothing was changed: ${[...new Set(problems)].join('; ')}`);

return [{ json: { counts, holders, held, accounts, members: seen.size, perBranch } }];

// Works out each Capacity row's Active Members from its "Glofox Memberships" names (one per line)
// and prepares the Airtable updates plus one Activity Log row describing what happened.
const { cfg } = $('Config').first().json;
const { counts, members } = $('Count Members').first().json;
const rows = $('Get Capacity').all().flatMap((i) => i.json.records || []);
const NOW = new Date().toISOString();

const used = new Set();
const updated = [];
const held = [];
const missing = [];
let unchanged = 0;
const writes = [];
for (const r of rows) {
  const names = String(r.fields['Glofox Memberships'] || '').split('\n').map((s) => s.trim()).filter(Boolean);
  if (!names.length) continue;
  const label = r.fields.Queue || `${r.fields.Location} · ${r.fields.Membership}`;
  let n = 0;
  for (const name of names) {
    const key = name.toLowerCase();
    used.add(key);
    if (counts[key]) n += counts[key].n;
    else missing.push(`${label}: "${name}"`);
  }
  const current = Number(r.fields['Active Members'] || 0);
  if (current >= cfg.minRowsForDropCheck && n < current * (1 - cfg.maxDropShare)) {
    held.push(`${label} ${current} → ${n}`);
    continue;
  }
  const fields = { 'Active Counted At': NOW };
  if (n !== current) { fields['Active Members'] = n; updated.push(`${label} ${current} → ${n}`); } else unchanged += 1;
  writes.push({ id: r.id, fields });
}
const notCounted = Object.entries(counts).filter(([k]) => !used.has(k)).sort((a, b) => b[1].n - a[1].n).map(([, v]) => `${v.name} (${v.n})`);

const detail = [
  updated.length ? `Updated: ${updated.join('; ')}` : 'No changes to Active Members.',
  `Unchanged: ${unchanged} queue(s). ${members} Glofox members read.`,
  held.length ? `Held back, count fell by more than ${Math.round(cfg.maxDropShare * 100)}% (check Glofox, then type the number in if it's right): ${held.join('; ')}` : '',
  missing.length ? `Glofox Memberships names not found in Glofox (typo, or nobody active on it): ${missing.join('; ')}` : '',
  notCounted.length ? `Active in Glofox but not counted in any queue: ${notCounted.join(', ')}` : '',
].filter(Boolean).join('\n');

const chunks = [];
for (let i = 0; i < writes.length; i += 10) chunks.push({ records: writes.slice(i, i + 10), typecast: true });
return [{
  json: {
    chunks,
    log: { records: [{ fields: { Summary: `Glofox sync · ${updated.length} queue(s) updated`, Timestamp: NOW, Event: 'Active Synced', Source: 'Glofox', Detail: detail } }], typecast: true },
    updated, held, missing, notCounted,
  },
}];

// Two daily jobs on the Waitlist, from the same Glofox read:
// 1) "Glofox Membership" lists what each person already holds (existing members get the upgrade invite).
// 2) Purchase verification for the revenue dashboard. Someone the waitlist invited counts as a verified purchase
//    ("Glofox Verified At") once Glofox shows them, by email, holding one of their queue's memberships (the Capacity
//    row's "Glofox Memberships" names, counted statuses only) that started no earlier than the day before their invite.
//    "Monthly Value" is what the person adds per month: the queue's price, or for an existing member's upgrade the
//    difference from the membership they already hold. Once verified it is fixed at the verified amount (Glofox's
//    monthly plan price when it has one). "Glofox Check" says, for people who signed up or asked for a tour, what
//    Glofox shows, so staff can follow up on sign-ups that never completed.
// Only fields that change are written. Each new verification adds one "Purchase Verified" row to the Activity Log.
const { cfg } = $('Config').first().json;
const { holders, held = {}, accounts = {} } = $('Count Members').first().json;
const rows = $('Get Waitlist').all().flatMap((i) => i.json.records || []);
const caps = $('Get Capacity').all().flatMap((i) => i.json.records || []);
const NOW = new Date().toISOString();
const counted = new Set(cfg.countStatuses.map((s) => String(s).toUpperCase()));
const DAY = 24 * 3600 * 1000;

const lc = (s) => String(s || '').trim().toLowerCase();
const queueKey = (loc, mem) => `${lc(loc)}|${lc(mem)}`;
const queues = {}; // location|membership → { price, names }
for (const c of caps) {
  const k = queueKey(c.fields.Location, c.fields.Membership);
  const q = (queues[k] = queues[k] || { price: 0, names: new Set() });
  if (!q.price && Number(c.fields.Price) > 0) q.price = Number(c.fields.Price);
  for (const n of String(c.fields['Glofox Memberships'] || '').split('\n').map(lc).filter(Boolean)) q.names.add(n);
}
const priceOfMembership = (name) => {
  for (const q of Object.values(queues)) if (q.price && q.names.has(lc(name))) return q.price;
  return 0;
};
const day = (iso) => new Date(iso).toLocaleDateString('en-US', { timeZone: 'America/New_York', month: 'short', day: 'numeric' });
const place = (loc) => (/^akari\b/i.test(String(loc || '')) ? loc : `Akari ${loc}`);

const writes = [];
const logs = [];
let verifiedTotal = 0;
for (const r of rows) {
  const f = r.fields;
  const email = lc(f.Email);
  const fields = {};

  const have = String(f['Glofox Membership'] || '').trim();
  const want = (holders[email] || []).slice().sort().join('; ');
  if (want !== have) fields['Glofox Membership'] = want || null;

  const q = queues[queueKey(f.Location, f.Membership)] || { price: 0, names: new Set() };
  const existing = f['Member Type'] === 'Existing';
  // What an upgrade adds is the difference from what they already pay (yesterday's "Glofox Membership").
  const paysNow = have ? Math.max(0, ...have.split(';').map(priceOfMembership)) : 0;
  const addsPerMonth = (price) => (price ? Math.max(price - (existing ? paysNow : 0), 0) : null);

  if (f['Glofox Verified At']) {
    verifiedTotal += 1;
  } else {
    const invitedAt = f['Invited At'] ? Date.parse(f['Invited At']) : NaN;
    const match = (held[email] || []).find((h) => q.names.has(lc(h.name)) && counted.has(h.status)
      && h.start && Date.parse(h.start) >= invitedAt - DAY);
    if (match) {
      const value = addsPerMonth(match.monthly && match.price ? match.price : q.price) || 0;
      const check = `Verified in Glofox: ${match.name} (${match.status.toLowerCase()}) from ${day(match.start)}${match.price ? `, $${match.price}/mo` : ''}`;
      Object.assign(fields, { 'Glofox Verified At': NOW, 'Monthly Value': value, 'Glofox Check': check });
      verifiedTotal += 1;
      logs.push({
        fields: {
          Summary: `Purchase verified: ${f.Name || f.Email} - ${f.Membership} at ${place(f.Location)}`,
          Timestamp: NOW, Event: 'Purchase Verified', Email: f.Email, Name: f.Name, Location: f.Location, Membership: f.Membership, Source: 'Glofox',
          Detail: `${check}. Adds $${value}/month${existing ? ' (upgrade: the difference from their previous membership)' : ''}.`,
          'Entry ID': r.id,
        },
      });
    } else {
      const value = addsPerMonth(q.price);
      if (value !== (f['Monthly Value'] ?? null)) fields['Monthly Value'] = value;
      let check = '';
      if (f.Status === 'Signed Up' || f.Status === 'Tour Requested') {
        const step = f.Status === 'Signed Up' ? 'Signed up' : 'Tour requested';
        const holds = (held[email] || []).filter((h) => counted.has(h.status)).map((h) => h.name);
        check = !accounts[email] ? `${step}; no Glofox account under this email yet`
          : holds.length ? `${step}; Glofox shows ${holds.join(', ')}, not this queue's membership yet`
            : `${step}; Glofox account, no membership yet`;
      }
      if (check !== String(f['Glofox Check'] || '')) fields['Glofox Check'] = check || null;
    }
  }
  if (Object.keys(fields).length) writes.push({ id: r.id, fields });
}
const chunk = (list) => {
  const out = [];
  for (let i = 0; i < list.length; i += 10) out.push({ records: list.slice(i, i + 10), typecast: true });
  return out;
};
return [{
  json: {
    chunks: chunk(writes), logChunks: chunk(logs), changed: writes.length, newlyVerified: logs.length, verifiedTotal,
    flagged: rows.filter((r) => holders[lc(r.fields.Email)]).length,
  },
}];
